(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(y*0.018+t*0.2)*12 + Math.cos((x+y)*0.012-t*0.15)*8;
  const w1y = Math.cos(x*0.02-t*0.18)*12 + Math.sin((x-y)*0.014+t*0.22)*8;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.025-t*0.3)*6 + Math.cos(sx*0.015+t*0.25)*4;
  const w2y = Math.cos(sx*0.022+t*0.28)*6 + Math.sin(sy*0.018-t*0.32)*4;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [120+Math.sin(t*0.4)*80, 60+Math.cos(t*0.3)*40, 0.07, 1.8],
    [360+Math.cos(t*0.35)*90, 50+Math.sin(t*0.45)*35, 0.085, 2.1],
    [80+Math.cos(t*0.5+1)*70, 170+Math.sin(t*0.4+2)*50, 0.065, 1.6],
    [400+Math.sin(t*0.45+3)*60, 180+Math.cos(t*0.35+1)*55, 0.095, 2.4],
    [240+Math.sin(t*0.25)*130, 120+Math.cos(t*0.35)*80, 0.055, 1.9],
    [200+Math.cos(t*0.55+2)*100, 200+Math.sin(t*0.3+4)*60, 0.075, 2.0],
    [300+Math.sin(t*0.4+5)*110, 90+Math.cos(t*0.5+3)*45, 0.08, 2.2],
    [160+Math.cos(t*0.3+4)*90, 30+Math.sin(t*0.55+1)*50, 0.06, 1.7]
  ];
  let aS=0, iS=0, hrm=0;
  for(const [sX,sY,f,sp] of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.5+1.5);
    hrm+=Math.sin(d*f*1.5-t*sp*1.3+0.7)*0.5;
  }
  const act=aS/8, inh=iS/8, hm=hrm/8;
  const bg=(Math.sin(fx*0.035+fy*0.022+t*0.7)*0.5+Math.sin(fx*0.025-fy*0.035+t*0.9)*0.4+Math.sin((fx+fy)*0.1+t*2.2)*0.15+Math.sin((fx-fy)*0.08-t*1.8)*0.15+Math.sin(fx*0.06+fy*0.04-t*1.5)*0.2)/1.4;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2), ang=Math.atan2(fy-cy, fx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3.5-t*1.3)*0.4+Math.sin(dist*0.035+ang*4.5-t*1.0)*0.3+Math.sin(dist*0.06-ang*2-t*1.8)*0.15)/0.85;
  const cell=Math.tanh((Math.sin(fx*0.12)*Math.sin(fy*0.12)*1.2+Math.sin((fx+fy)*0.08+t*0.5)*0.6+Math.sin(fx*0.2)*Math.cos(fy*0.15-t*0.3)*0.4)*1.3)*0.25;
  const rd1=Math.tanh((act-inh*0.65+bg*0.35+spiral*0.4+hm*0.3)*2.0);
  const rd2=Math.tanh((inh-act*0.5+spiral*0.3-hm*0.2+cell)*1.8);
  const cross=Math.tanh((rd1-rd2*0.4)*1.5);
  const edge=Math.abs(cross)>0.65?1.0+Math.abs(cross)*0.2:1.0;
  const glow=Math.max(0, Math.abs(cross)-0.5)*0.5;
  const breath=1.0+Math.sin(t*0.3)*0.05;
  const v=(cross*0.5+0.5+glow*0.1)*breath;
  const pal=[[5,12,55],[10,45,90],[12,85,120],[18,130,130],[60,160,120],[140,175,90],[210,175,65],[220,130,60],[195,85,55],[150,50,60],[90,25,55],[40,15,50],[5,12,55]];
  const idx=v*(pal.length-1), i=Math.min(idx|0, pal.length-2), f=idx-i;
  const lum=0.85+Math.sin(cross*Math.PI)*0.15, bright=edge*lum;
  return [
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*bright)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*bright)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*bright)|0
  ];
}
